const cards = [0, 1, 2, 3, 4].map(i => root.querySelector('#c' + i));
const starVal = root.querySelector('#starVal');
const lines = [0, 1, 2, 3].map(i => {
  const el = root.querySelector('#l' + i);
  const len = el.getTotalLength();
  el.style.strokeDasharray = len;
  el.style.strokeDashoffset = len;
  return { el, len };
});

function frame(t, p, d) {
  const isSettled = p >= 0.55;

  // Reveal cards sequentially
  cards.forEach((card, i) => {
    const s = spr(t, i * 0.1, 0.8, 8);
    card.style.opacity = s;
    card.style.transform = `translateY(${(1 - s) * 40}px) scale(${0.9 + s * 0.1})`;
  });

  // Animate GitHub Stars Counter
  const countP = E_OUT(clamp(p * 2.2));
  const currentStars = Math.floor(lerp(0, 319386, countP));
  starVal.textContent = currentStars.toLocaleString();

  // Animate connector lines
  lines.forEach((l, i) => {
    const lp = clamp((p - 0.2 - i * 0.05) * 3);
    l.el.style.strokeDashoffset = l.len * (1 - E_INOUT(lp));
  });

  if (isSettled) {
    starVal.textContent = "319,386";
    cards.forEach(c => {
      c.style.opacity = 1;
      c.style.transform = 'translateY(0) scale(1)';
    });
    lines.forEach(l => l.el.style.strokeDashoffset = 0);
  }
}
